          label="Full Name"
          required={true}
          value={formData.fullName}
          onChange={handleChange}
          error={errors.fullName}
          autocomplete="name"
        />
        <FormField
          id="email"
          label="Email Address"
          type="email"
          required={true}
          value={formData.email}
          onChange={handleChange}
          error={errors.email}
          autocomplete="email"
        />
        <FormField
          id="phone"
          label="Phone Number"
          type="tel"
          required={false}
          helperText="Format: (XXX) XXX-XXXX"
          value={formData.phone}
          onChange={handleChange}
          error={errors.phone}
          autocomplete="tel"
        />
        <button type="submit">Submit Request</button>
      </form>
    </div>
  );
};

const App = () => {
  return (
    <main role="main">
      <ContactForm />
    </main>
  );
};

