 const { useState, useRef } = React;

 const FormField = ({ label, id, type = "text", required = false, helperText, value, onChange, error, autocomplete }) => {
   const helperId = `${id}-helper`;
   const errorId = `${id}-error`;
   const describedBy = [
     helperText ? helperId : null,
     error ? errorId : null
   ].filter(Boolean).join(" ");

   return (
     <div className="form-field">
       <label htmlFor={id}>
         {label}
         {required && <span className="required-asterisk" aria-hidden="true">*</span>}
         {required && <span className="sr-only">(required)</span>}
       </label>
       <input
         id={id}
         name={id}
         type={type}
         required={required}
         value={value}
         onChange={onChange}
         aria-invalid={!!error}
         aria-describedby={describedBy || undefined}
         autoComplete={autocomplete}
       />
       {helperText && <div id={helperId} className="helper-text">{helperText}</div>}
       {error && <div id={errorId} className="error-message" role="alert">Error: {error}</div>}
     </div>
   );
 };

 const ContactForm = () => {
   const [formData, setFormData] = useState({
     fullName: "",
     email: "",
     phone: ""
   });
   const [errors, setErrors] = useState({});
   const [submitted, setSubmitted] = useState(false);

   // Refs for focusing first error
   const fieldRefs = {
     fullName: useRef(null),
     email: useRef(null),
     phone: useRef(null)
   };

   const handleChange = (e) => {
     const { name, value } = e.target;
     setFormData(prev => ({ ...prev, [name]: value }));
     // Clear error when user types
     if (errors[name]) {
       setErrors(prev => {
         const newErrors = { ...prev };
         delete newErrors[name];
         return newErrors;
       });
     }
   };

   const validate = () => {
     const newErrors = {};
     if (!formData.fullName.trim()) {
       newErrors.fullName = "Full name is required";
     }

     if (!formData.email.trim()) {
       newErrors.email = "Email address is required";
     } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
       newErrors.email = "Please enter a valid email address";
     }

     // Phone is optional, but if we wanted to validate format:
     // if (formData.phone && !/^\(\d{3}\) \d{3}-\d{4}$/.test(formData.phone)) {
     //   newErrors.phone = "Phone must be in format (XXX) XXX-XXXX";
     // }

     return newErrors;
   };

   const handleSubmit = (e) => {
     e.preventDefault();
     const newErrors = validate();

     if (Object.keys(newErrors).length > 0) {
       setErrors(newErrors);
       setSubmitted(false);

       // Focus the first field with an error
       const firstErrorField = Object.keys(newErrors)[0];
       const inputElement = document.getElementById(firstErrorField);
       if (inputElement) {
         inputElement.focus();
       }
     } else {
       setErrors({});
       setSubmitted(true);
       console.log("Form submitted:", formData);
     }
   };

   if (submitted) {
     return (
       <div className="container" role="status">
         <h1>Thank You!</h1>
         <p className="success-message">Your support request has been sent successfully.</p>
         <button onClick={() => setSubmitted(false)}>Send another message</button>
       </div>
     );
   }

   return (
     <div className="container">
       <h1>Contact Support</h1>
       <form onSubmit={handleSubmit} noValidate>
         <FormField
           id="fullName"
           label="Full Name"
           required={true}
           value={formData.fullName}
           onChange={handleChange}
           error={errors.fullName}
           autocomplete="name"
         />
         <FormField
           id="email"
           label="Email Address"
           type="email"
           required={true}
           value={formData.email}
           onChange={handleChange}
           error={errors.email}
           autocomplete="email"
         />
         <FormField
           id="phone"
           label="Phone Number"
           type="tel"
           required={false}
           helperText="Format: (XXX) XXX-XXXX"
           value={formData.phone}
           onChange={handleChange}
           error={errors.phone}
           autocomplete="tel"
         />
         <button type="submit">Submit Request</button>
       </form>
     </div>
   );
 };

 const App = () => {
   return (
     <main role="main">
       <ContactForm />
     </main>
   );
 };

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<App />);

