            border-color: var(--error-color);
        }

        .helper-text {
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-top: 0.25rem;
        }

        .error-message {
            font-size: 0.85rem;
            color: var(--error-color);
            margin-top: 0.25rem;
        }

        button {
            background-color: var(--primary-color);
            color: #000;
            border: none;
            border-radius: 4px;
            padding: 0.75rem 1.5rem;
            font-size: 1rem;
            font-weight: bold;
            cursor: pointer;
            transition: background-color 0.2s;
            width: 100%;
            margin-top: 1rem;
        }

        button:hover {
            background-color: #a370f0;
        }

        button:focus {
            outline: none;
            box-shadow: 0 0 0 3px rgba(187, 134, 252, 0.5);
        }

        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
