    <title>Support - Contact Us</title>
    <!-- React CDNs -->
    <script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
    <!-- Babel for JSX -->
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <style>
        :root {
            --bg-color: #121212;
            --surface-color: #1e1e1e;
            --text-primary: #e0e0e0;
            --text-secondary: #b0b0b0;
            --primary-color: #bb86fc;
            --error-color: #ff8091;
            --input-bg: #2c2c2c;
            --border-color: #444;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-primary);
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        .container {
            background-color: var(--surface-color);
            padding: 2rem;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
            width: 100%;
            max-width: 450px;
        }

        h1 {
            margin-top: 0;
            font-size: 1.5rem;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 1rem;
            margin-bottom: 1.5rem;
        }

        .form-field {
            margin-bottom: 1.5rem;
            display: flex;
            flex-direction: column;
        }

        label {
            margin-bottom: 0.5rem;
            font-weight: 500;
            color: var(--text-primary);
        }

        .required-asterisk {
            color: var(--error-color);
            margin-left: 2px;
        }

        input {
            background-color: var(--input-bg);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            color: var(--text-primary);
            padding: 0.75rem;
            font-size: 1rem;
            transition: border-color 0.2s, box-shadow 0.2s;
        }

        input:focus {
            outline: none;
            border-color: var(--primary-color);
            box-shadow: 0 0 0 2px rgba(187, 134, 252, 0.3);
        }

        input[aria-invalid="true"] {
            border-color: var(--error-color);
        }

        .helper-text {
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-top: 0.25rem;
        }

        .error-message {
            font-size: 0.85rem;
            color: var(--error-color);
            margin-top: 0.25rem;
        }

        button {
            background-color: var(--primary-color);
            color: #000;
            border: none;
            border-radius: 4px;
            padding: 0.75rem 1.5rem;
            font-size: 1rem;
            font-weight: bold;
            cursor: pointer;
            transition: background-color 0.2s;
            width: 100%;
            margin-top: 1rem;
        }

        button:hover {
            background-color: #a370f0;
        }

        button:focus {
            outline: none;
            box-shadow: 0 0 0 3px rgba(187, 134, 252, 0.5);
        }

        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            border: 0;
        }

        .success-message {
            color: #4caf50;
            text-align: center;
            font-weight: bold;
        }
    </style>
</head>
<body>
    <div id="root"></div>
    <script type="text/babel">
        const { useState, useRef } = React;

        const FormField = ({ label, id, type = "text", required = false, helperText, value, onChange, error, autocomplete }) => {
          const helperId = `${id}-helper`;
          const errorId = `${id}-error`;
          const describedBy = [
            helperText ? helperId : null,
            error ? errorId : null
          ].filter(Boolean).join(" ");

          return (
            <div className="form-field">
              <label htmlFor={id}>
                {label}
                {required && <span className="required-asterisk" aria-hidden="true">*</span>}
                {required && <span className="sr-only">(required)</span>}
              </label>
              <input
                id={id}
                name={id}
                type={type}
                required={required}
                value={value}
                onChange={onChange}
                aria-invalid={!!error}
                aria-describedby={describedBy || undefined}
                autoComplete={autocomplete}
              />
              {helperText && <div id={helperId} className="helper-text">{helperText}</div>}
              {error && <div id={errorId} className="error-message" role="alert">Error: {error}</div>}
            </div>
          );
        };

        const ContactForm = () => {
          const [formData, setFormData] = useState({
            fullName: "",
            email: "",
            phone: ""
          });
          const [errors, setErrors] = useState({});
          const [submitted, setSubmitted] = useState(false);

          const handleChange = (e) => {
            const { name, value } = e.target;
            setFormData(prev => ({ ...prev, [name]: value }));
            if (errors[name]) {
              setErrors(prev => {
                const newErrors = { ...prev };
                delete newErrors[name];
                return newErrors;
              });
            }
          };

          const validate = () => {
            const newErrors = {};
            if (!formData.fullName.trim()) {
              newErrors.fullName = "Full name is required";
            }

            if (!formData.email.trim()) {
              newErrors.email = "Email address is required";
            } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
              newErrors.email = "Please enter a valid email address";
            }
            return newErrors;
          };

          const handleSubmit = (e) => {
            e.preventDefault();
            const newErrors = validate();

            if (Object.keys(newErrors).length > 0) {
              setErrors(newErrors);
              setSubmitted(false);

              const firstErrorField = Object.keys(newErrors)[0];
              const inputElement = document.getElementById(firstErrorField);
              if (inputElement) {
                inputElement.focus();
              }
            } else {
              setErrors({});
              setSubmitted(true);
              console.log("Form submitted:", formData);
            }
          };

          if (submitted) {
            return (
              <div className="container" role="status">
                <h1>Thank You!</h1>
                <p className="success-message">Your support request has been sent successfully.</p>
                <button onClick={() => setSubmitted(false)}>Send another message</button>
              </div>
            );
          }

          return (
            <div className="container">
              <h1>Contact Support</h1>
              <form onSubmit={handleSubmit} noValidate>
                <FormField
                  id="fullName"
                  label="Full Name"
                  required={true}
                  value={formData.fullName}
                  onChange={handleChange}
                  error={errors.fullName}
                  autocomplete="name"
                />
                <FormField
                  id="email"
                  label="Email Address"
                  type="email"
                  required={true}
                  value={formData.email}
                  onChange={handleChange}
                  error={errors.email}
                  autocomplete="email"
                />
                <FormField
                  id="phone"
                  label="Phone Number"
                  type="tel"
                  required={false}
                  helperText="Format: (XXX) XXX-XXXX"
                  value={formData.phone}
                  onChange={handleChange}
                  error={errors.phone}
                  autocomplete="tel"
                />
                <button type="submit">Submit Request</button>
              </form>
            </div>
          );
        };

        const App = () => {
          return (
            <main>
              <ContactForm />
            </main>
          );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
